		t.Fatalf("未被引用的课程应允许修改，得到 action=%v err=%v", a, err)
	}

	mustReq(t, s, "s1", "r1", "c1")
	// 被要求引用后不能改学分。
	if _, _, err := s.AddCourse("c1", "高等数学", 6); err == nil {
		t.Fatal("已被要求引用的课程不应允许修改学分")
