// RevokeWaiver 撤销有效免修，原依据与撤销状态保留；reason 可填撤销原因。
// 重复撤销已撤销的免修：原样返回、不改变结果。撤销不存在的编号或撤销
// 已被拒绝的申请：明确拒绝。
func (s *Store) RevokeWaiver(studentID, waiverID, reason string) (w *Waiver, err error) {
	studentID = strings.TrimSpace(studentID)
	waiverID = strings.TrimSpace(waiverID)
	reason = strings.TrimSpace(reason)
	if _, ok := s.studentByID[studentID]; !ok {
		return nil, fmt.Errorf("学生 %s 不存在", studentID)
	}
	w = s.waiverByKey[reqKey(studentID, waiverID)]
	if w == nil {
		return nil, fmt.Errorf("学生 %s 名下不存在免修 %s，不能撤销", studentID, waiverID)
	}
	switch w.Status {
	case WaiverApproved:
		w.Status = WaiverRevoked
		if reason == "" {
			reason = "手动撤销"
		}
		w.Reason = reason
		s.dirty = true
		return w, nil
	case WaiverRevoked:
		return w, nil
	default:
		return nil, fmt.Errorf("免修 %s 已被拒绝，不能撤销（拒绝原因：%s）", waiverID, w.Reason)
	}
}

